#!/usr/bin/env python3
"""
Coverage-guided fuzzing for Arrow library using atheris (LibFuzzer compatible).

Targets:
- DateTimeParser.parse_iso(): ISO 8601 datetime string parsing
- DateTimeParser.parse(): Custom format datetime parsing
- TzinfoParser.parse(): Timezone string parsing
- Arrow.dehumanize(): Human-readable time string parsing
- arrow.get(): Flexible Arrow object construction
"""

import sys
import atheris


def setup_arrow():
    """Import arrow and related modules."""
    global arrow, DateTimeParser, TzinfoParser
    import arrow as arrow_module
    from arrow.parser import DateTimeParser as DTP, TzinfoParser as TZP
    arrow = arrow_module
    DateTimeParser = DTP
    TzinfoParser = TZP


def fuzz_parse_iso(data: bytes):
    """Fuzz DateTimeParser.parse_iso() with arbitrary strings."""
    try:
        string = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    parser = DateTimeParser()
    try:
        parser.parse_iso(string)
    except (arrow.parser.ParserError, ValueError, OverflowError):
        pass


def fuzz_parse_with_format(data: bytes):
    """Fuzz DateTimeParser.parse() with both datetime string and format."""
    try:
        # Split data into datetime string and format using null byte separator
        if b'\x00' not in data:
            return
        parts = data.split(b'\x00', 1)
        datetime_str = parts[0].decode('utf-8')
        fmt = parts[1].decode('utf-8')
    except (UnicodeDecodeError, IndexError):
        return

    parser = DateTimeParser()
    try:
        parser.parse(datetime_str, fmt)
    except (arrow.parser.ParserError, ValueError, OverflowError, KeyError, AttributeError):
        pass
    except Exception:
        # Catch regex errors and other parsing issues
        pass


def fuzz_timezone_parse(data: bytes):
    """Fuzz TzinfoParser.parse() with timezone strings."""
    try:
        string = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        TzinfoParser.parse(string)
    except (arrow.parser.ParserError, ValueError, KeyError):
        pass


def fuzz_dehumanize(data: bytes):
    """Fuzz Arrow.dehumanize() with human-readable time strings."""
    try:
        string = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        arw = arrow.utcnow()
        arw.dehumanize(string)
    except (ValueError, AttributeError, TypeError):
        pass


def fuzz_arrow_get(data: bytes):
    """Fuzz arrow.get() with arbitrary strings."""
    try:
        string = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        arrow.get(string)
    except (arrow.parser.ParserError, TypeError, ValueError, OverflowError):
        pass


def TestOneInput(data: bytes):
    """Main fuzzing entry point - calls all fuzz targets."""
    if len(data) < 1:
        return

    # Use first byte to select target
    selector = data[0] % 5
    payload = data[1:]

    if selector == 0:
        fuzz_parse_iso(payload)
    elif selector == 1:
        fuzz_parse_with_format(payload)
    elif selector == 2:
        fuzz_timezone_parse(payload)
    elif selector == 3:
        fuzz_dehumanize(payload)
    else:
        fuzz_arrow_get(payload)


def main():
    """Main entry point for the fuzzer."""
    setup_arrow()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Coverage-guided fuzzing for Black code formatter using atheris (LibFuzzer compatible).

Targets:
- format_str(): Main public API for formatting Python code
- lib2to3_parse(): Core parsing function
- parse_ast(): Standard library AST parsing
- decode_bytes(): Encoding detection from raw bytes
"""

import sys
import atheris


def setup_black():
    """Import black and related modules."""
    global black, Mode, TargetVersion, lib2to3_parse, parse_ast
    import black as black_module
    from black import Mode as M
    from black.mode import TargetVersion as TV
    from black.parsing import lib2to3_parse as l2tp, parse_ast as pa
    black = black_module
    Mode = M
    TargetVersion = TV
    lib2to3_parse = l2tp
    parse_ast = pa


def fuzz_format_str(data: bytes):
    """Fuzz black.format_str() with arbitrary source code."""
    try:
        src = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        mode = Mode()
        black.format_str(src, mode=mode)
    except (black.InvalidInput, ValueError, RecursionError):
        pass
    except Exception:
        # Catch any other parsing/formatting errors
        pass


def fuzz_format_str_with_options(data: bytes):
    """Fuzz black.format_str() with various Mode options."""
    if len(data) < 2:
        return

    try:
        # Use first byte for options
        options = data[0]
        src = data[1:].decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        # Vary Mode parameters based on options byte
        line_length = 40 + (options & 0x3F)  # 40-103
        is_pyi = bool(options & 0x40)
        string_normalization = bool(options & 0x80)

        mode = Mode(
            line_length=line_length,
            is_pyi=is_pyi,
            string_normalization=string_normalization
        )
        black.format_str(src, mode=mode)
    except (black.InvalidInput, ValueError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_lib2to3_parse(data: bytes):
    """Fuzz lib2to3_parse() with arbitrary source code."""
    try:
        src = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        lib2to3_parse(src)
    except (black.InvalidInput, ValueError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_parse_ast(data: bytes):
    """Fuzz parse_ast() with arbitrary source code."""
    try:
        src = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        parse_ast(src)
    except (SyntaxError, ValueError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_decode_bytes(data: bytes):
    """Fuzz decode_bytes() with arbitrary byte sequences."""
    try:
        mode = Mode()
        black.decode_bytes(data, mode)
    except (ValueError, UnicodeDecodeError, LookupError):
        pass
    except Exception:
        pass


def TestOneInput(data: bytes):
    """Main fuzzing entry point - calls all fuzz targets."""
    if len(data) < 1:
        return

    # Use first byte to select target
    selector = data[0] % 5
    payload = data[1:]

    if selector == 0:
        fuzz_format_str(payload)
    elif selector == 1:
        fuzz_format_str_with_options(payload)
    elif selector == 2:
        fuzz_lib2to3_parse(payload)
    elif selector == 3:
        fuzz_parse_ast(payload)
    else:
        fuzz_decode_bytes(payload)


def main():
    """Main entry point for the fuzzer."""
    setup_black()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Coverage-guided fuzzing for IPython library using atheris (LibFuzzer compatible).

Targets:
- TransformerManager.transform_cell(): Main input transformation
- TransformerManager.check_complete(): Completion detection
- split_user_input(): Line splitting
- Magics.parse_options(): Magic argument parsing
- guarded_eval(): Safe evaluation
"""

import sys
import atheris


def setup_ipython():
    """Import IPython and related modules."""
    global TransformerManager, split_user_input, guarded_eval, EvaluationContext, EvaluationPolicy
    from IPython.core.inputtransformer2 import TransformerManager as TM
    from IPython.core.splitinput import split_user_input as sui
    from IPython.core.guarded_eval import guarded_eval as ge, EvaluationContext as EC, EvaluationPolicy as EP
    TransformerManager = TM
    split_user_input = sui
    guarded_eval = ge
    EvaluationContext = EC
    EvaluationPolicy = EP


def fuzz_transform_cell(data: bytes):
    """Fuzz TransformerManager.transform_cell() with arbitrary cell content."""
    try:
        cell = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        tm = TransformerManager()
        tm.transform_cell(cell)
    except (SyntaxError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def fuzz_check_complete(data: bytes):
    """Fuzz TransformerManager.check_complete() with partial input."""
    try:
        cell = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        tm = TransformerManager()
        tm.check_complete(cell)
    except (SyntaxError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def fuzz_split_user_input(data: bytes):
    """Fuzz split_user_input() with arbitrary line input."""
    try:
        line = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        split_user_input(line)
    except (ValueError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_guarded_eval(data: bytes):
    """Fuzz guarded_eval() with code strings."""
    try:
        code = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        # Use a minimal/restrictive policy for safety
        policy = EvaluationPolicy(
            allow_builtins_access=True,
            allow_locals_access=True,
            allow_globals_access=False,
            allow_item_access=True,
            allow_attr_access=True,
            allowed_calls=set(),
        )
        context = EvaluationContext(
            locals={},
            globals={},
            evaluation=policy,
        )
        guarded_eval(code, context)
    except (SyntaxError, ValueError, TypeError, NameError, AttributeError, KeyError):
        pass
    except Exception:
        pass


def fuzz_magic_commands(data: bytes):
    """Fuzz magic command parsing via transform_cell."""
    try:
        base = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    # Prefix with magic indicators
    magic_prefixes = ['%', '%%', '!', '!!', '?', '??', '/', ',', ';']
    for prefix in magic_prefixes:
        cell = prefix + base
        try:
            tm = TransformerManager()
            tm.transform_cell(cell)
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            pass
        except Exception:
            pass


def TestOneInput(data: bytes):
    """Main fuzzing entry point - calls all fuzz targets."""
    if len(data) < 1:
        return

    # Use first byte to select target
    selector = data[0] % 5
    payload = data[1:]

    if selector == 0:
        fuzz_transform_cell(payload)
    elif selector == 1:
        fuzz_check_complete(payload)
    elif selector == 2:
        fuzz_split_user_input(payload)
    elif selector == 3:
        fuzz_guarded_eval(payload)
    else:
        fuzz_magic_commands(payload)


def main():
    """Main entry point for the fuzzer."""
    setup_ipython()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Coverage-guided fuzzing for MiniSGL library using atheris (LibFuzzer compatible).

Targets:
- deserialize_type(): Message deserialization with type handling
- _deserialize_any(): Recursive deserialization
- OpenAI API request parsing via Pydantic models
- Memory size parsing (_PARSE_MEM_BYTES)
"""

import sys
import atheris


def setup_minisgl():
    """Import minisgl and related modules."""
    global deserialize_type, _deserialize_any, serialize_type, _PARSE_MEM_BYTES
    global OpenAICompletionRequest, GenerateRequest, Message
    global BaseBackendMsg, BaseFrontendMsg, BaseTokenizerMsg
    global np

    import numpy as np_module
    np = np_module

    from minisgl.message.utils import deserialize_type as dt, _deserialize_any as da, serialize_type as st
    deserialize_type = dt
    _deserialize_any = da
    serialize_type = st

    from minisgl.env import _PARSE_MEM_BYTES as pmb
    _PARSE_MEM_BYTES = pmb

    from minisgl.server.api_server import OpenAICompletionRequest as OACR, GenerateRequest as GR, Message as M
    OpenAICompletionRequest = OACR
    GenerateRequest = GR
    Message = M

    from minisgl.message.backend import BaseBackendMsg as BBM
    from minisgl.message.frontend import BaseFrontendMsg as BFM
    from minisgl.message.tokenizer import BaseTokenizerMsg as BTM
    BaseBackendMsg = BBM
    BaseFrontendMsg = BFM
    BaseTokenizerMsg = BTM


def fuzz_deserialize_type(data: bytes):
    """Fuzz deserialize_type() with crafted dictionaries."""
    try:
        import msgpack
        raw_dict = msgpack.unpackb(data, raw=False, strict_map_key=False)
        if not isinstance(raw_dict, dict):
            return
    except Exception:
        return

    # Create a mock cls_map with common message types
    cls_map = {}
    try:
        from minisgl.message.backend import UserMsg, ExitMsg, BatchBackendMsg
        from minisgl.message.frontend import UserReply, BatchFrontendMsg
        cls_map = {
            "UserMsg": UserMsg,
            "ExitMsg": ExitMsg,
            "BatchBackendMsg": BatchBackendMsg,
            "UserReply": UserReply,
            "BatchFrontendMsg": BatchFrontendMsg,
        }
    except Exception:
        pass

    try:
        deserialize_type(cls_map, raw_dict)
    except (TypeError, ValueError, KeyError, AttributeError, OverflowError):
        pass
    except Exception:
        pass


def fuzz_deserialize_any(data: bytes):
    """Fuzz _deserialize_any() with nested structures."""
    try:
        import msgpack
        raw_data = msgpack.unpackb(data, raw=False, strict_map_key=False)
    except Exception:
        return

    cls_map = {}
    try:
        _deserialize_any(cls_map, raw_data)
    except (TypeError, ValueError, KeyError, AttributeError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_pydantic_models(data: bytes):
    """Fuzz Pydantic API models with JSON-like data."""
    try:
        import json
        json_data = json.loads(data.decode('utf-8'))
        if not isinstance(json_data, dict):
            return
    except (UnicodeDecodeError, json.JSONDecodeError):
        return

    # Fuzz OpenAICompletionRequest
    try:
        OpenAICompletionRequest(**json_data)
    except Exception:
        pass

    # Fuzz GenerateRequest
    try:
        GenerateRequest(**json_data)
    except Exception:
        pass

    # Fuzz Message
    try:
        Message(**json_data)
    except Exception:
        pass


def fuzz_parse_mem_bytes(data: bytes):
    """Fuzz _PARSE_MEM_BYTES() with memory size strings."""
    try:
        mem_str = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        _PARSE_MEM_BYTES(mem_str)
    except (ValueError, TypeError, OverflowError):
        pass
    except Exception:
        pass


def fuzz_tensor_deserialization(data: bytes):
    """Fuzz tensor buffer handling in deserialize_type."""
    if len(data) < 10:
        return

    # Create a tensor-like dictionary structure
    dtype_options = ["float32", "float64", "int32", "int64", "float16", "uint8"]
    dtype_idx = data[0] % len(dtype_options)
    dtype_str = dtype_options[dtype_idx]
    buffer_data = bytes(data[1:])

    tensor_dict = {
        "__type__": "Tensor",
        "buffer": buffer_data,
        "dtype": f"torch.{dtype_str}"
    }

    cls_map = {}
    try:
        deserialize_type(cls_map, tensor_dict)
    except (TypeError, ValueError, AttributeError, OverflowError):
        pass
    except Exception:
        pass


def TestOneInput(data: bytes):
    """Main fuzzing entry point - calls all fuzz targets."""
    if len(data) < 1:
        return

    # Use first byte to select target
    selector = data[0] % 5
    payload = data[1:]

    if selector == 0:
        fuzz_deserialize_type(payload)
    elif selector == 1:
        fuzz_deserialize_any(payload)
    elif selector == 2:
        fuzz_pydantic_models(payload)
    elif selector == 3:
        fuzz_parse_mem_bytes(payload)
    else:
        fuzz_tensor_deserialization(payload)


def main():
    """Main entry point for the fuzzer."""
    setup_minisgl()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Coverage-guided fuzzing for ujson library using atheris (LibFuzzer compatible).

Targets:
- ujson.loads()/ujson.decode(): JSON string/bytes to Python object
- ujson.dumps()/ujson.encode(): Python object to JSON string (round-trip)
- Various edge cases: deep nesting, unicode, numeric overflow
"""

import sys
import atheris


def setup_ujson():
    """Import ujson module."""
    global ujson
    import ujson as ujson_module
    ujson = ujson_module


def fuzz_loads_str(data: bytes):
    """Fuzz ujson.loads() with string input."""
    try:
        json_str = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        ujson.loads(json_str)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def fuzz_loads_bytes(data: bytes):
    """Fuzz ujson.loads() with bytes input."""
    try:
        ujson.loads(data)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError, UnicodeDecodeError):
        pass
    except Exception:
        pass


def fuzz_loads_with_precise_float(data: bytes):
    """Fuzz ujson.loads() with precise_float option."""
    try:
        json_str = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        ujson.loads(json_str)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def fuzz_roundtrip(data: bytes):
    """Fuzz encode-decode roundtrip."""
    try:
        json_str = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        # Parse the input as JSON
        obj = ujson.loads(json_str)
        # Re-encode and decode
        encoded = ujson.dumps(obj)
        ujson.loads(encoded)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError, TypeError, OverflowError):
        pass
    except Exception:
        pass


def fuzz_dumps_options(data: bytes):
    """Fuzz ujson.dumps() with various options."""
    if len(data) < 2:
        return

    options = data[0]
    try:
        json_str = data[1:].decode('utf-8')
    except UnicodeDecodeError:
        return

    try:
        obj = ujson.loads(json_str)
    except Exception:
        return

    # Vary encoding options
    ensure_ascii = bool(options & 0x01)
    encode_html_chars = bool(options & 0x02)
    escape_forward_slashes = bool(options & 0x04)
    sort_keys = bool(options & 0x08)
    indent = (options >> 4) & 0x07  # 0-7

    try:
        ujson.dumps(
            obj,
            ensure_ascii=ensure_ascii,
            encode_html_chars=encode_html_chars,
            escape_forward_slashes=escape_forward_slashes,
            sort_keys=sort_keys,
            indent=indent
        )
    except (ValueError, TypeError, OverflowError, RecursionError):
        pass
    except Exception:
        pass


def fuzz_deep_nesting(data: bytes):
    """Fuzz with deeply nested structures."""
    if len(data) < 1:
        return

    # Create nested structure based on input
    depth = min(data[0], 200)  # Limit depth to avoid stack overflow
    rest = data[1:10] if len(data) > 1 else b"1"

    # Build nested array JSON
    nested_array = "[" * depth + rest.decode('utf-8', errors='replace') + "]" * depth

    try:
        ujson.loads(nested_array)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass

    # Build nested object JSON
    nested_obj = '{"a":' * depth + '"x"' + '}' * depth

    try:
        ujson.loads(nested_obj)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def fuzz_numeric_edge_cases(data: bytes):
    """Fuzz numeric parsing edge cases."""
    try:
        json_str = data.decode('utf-8')
    except UnicodeDecodeError:
        return

    # Try parsing as a number in JSON array context
    numeric_json = f"[{json_str}]"
    try:
        ujson.loads(numeric_json)
    except (ujson.JSONDecodeError, ValueError, RecursionError, MemoryError):
        pass
    except Exception:
        pass


def TestOneInput(data: bytes):
    """Main fuzzing entry point - calls all fuzz targets."""
    if len(data) < 1:
        return

    # Use first byte to select target
    selector = data[0] % 7
    payload = data[1:]

    if selector == 0:
        fuzz_loads_str(payload)
    elif selector == 1:
        fuzz_loads_bytes(payload)
    elif selector == 2:
        fuzz_loads_with_precise_float(payload)
    elif selector == 3:
        fuzz_roundtrip(payload)
    elif selector == 4:
        fuzz_dumps_options(payload)
    elif selector == 5:
        fuzz_deep_nesting(payload)
    else:
        fuzz_numeric_edge_cases(payload)


def main():
    """Main entry point for the fuzzer."""
    setup_ujson()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()


if __name__ == "__main__":
    main()

