- ujson.dumps()/ujson.encode(): Python object to JSON string (round-trip)
- Various edge cases: deep nesting, unicode, numeric overflow
"""

import sys
import atheris


def setup_ujson():
    """Import ujson module."""
    global ujson
    import ujson as ujson_module
