    mem = mem.strip().upper()
    if not mem:
        raise ValueError("Empty memory string")

    suffix_multipliers = {
        'K': 1024,
        'M': 1024 ** 2,
        'G': 1024 ** 3,
        'T': 1024 ** 4,
    }

    if mem[-1] in suffix_multipliers:
        multiplier = suffix_multipliers[mem[-1]]
        value = float(mem[:-1])
